// src/utils/sm2Engine.ts
function processSm2Review(card, rating) {
  let { repetitions = 0, interval = 0, easeFactor = 2.5 } = card;
  const sm2Score = rating === 0 ? 1 : rating === 1 ? 3 : rating === 2 ? 4 : 5;
  easeFactor = easeFactor + (0.1 - (5 - sm2Score) * (0.08 + (5 - sm2Score) * 0.02));
  if (easeFactor < 1.3) easeFactor = 1.3;
  if (rating < 2) {
    repetitions = 0;
    interval = 1;
  } else {
    if (repetitions === 0) {
      interval = 1;
    } else if (repetitions === 1) {
      interval = 6;
    } else {
      interval = Math.round(interval * easeFactor);
    }
    repetitions += 1;
    if (rating === 3) {
      interval = Math.round(interval * 1.2);
    }
  }
  const nextDate = /* @__PURE__ */ new Date();
  nextDate.setDate(nextDate.getDate() + interval);
  return {
    ...card,
    repetitions,
    interval,
    easeFactor: Number(easeFactor.toFixed(2)),
    nextReviewDate: formatDateIso(nextDate),
    lastReviewedAt: formatDateIso(/* @__PURE__ */ new Date())
  };
}

