// src/utils/audio.ts
function playChimeSound() {
  try {
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    const ctx = new AudioCtx();
    const now = ctx.currentTime;
    const notes = [659.25, 830.61, 987.77, 1318.51];
    notes.forEach((freq, index2) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = "sine";
      osc.frequency.setValueAtTime(freq, now + index2 * 0.08);
      gain.gain.setValueAtTime(0, now + index2 * 0.08);
      gain.gain.linearRampToValueAtTime(0.2, now + index2 * 0.08 + 0.02);
      gain.gain.exponentialRampToValueAtTime(1e-4, now + index2 * 0.08 + 1.2);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(now + index2 * 0.08);
      osc.stop(now + index2 * 0.08 + 1.3);
    });
  } catch (e) {
    console.warn("Could not play audio chime:", e);
  }
}

