var import_obsidian4 = require("obsidian");
var VIEW_TYPE_CONCEPT_MAP = "study-hub-concept-map";
var ConceptMapView = class extends import_obsidian4.ItemView {
  constructor(leaf) {
    super(leaf);
    __publicField(this, "component");
  }
  getViewType() {
    return VIEW_TYPE_CONCEPT_MAP;
  }
  getDisplayText() {
    return "3D Concept Map";
  }
  getIcon() {
    return "network";
  }
  async onOpen() {
    const store = get(studyHubStore);
    const defaultCourse = store.courses[0] || { id: "dsa", title: "Data Structures & Algorithms" };
    this.contentEl.empty();
    this.contentEl.style.padding = "0";
    this.contentEl.style.height = "100%";
    this.contentEl.style.overflow = "hidden";
    this.component = mount(ConceptMap3D, {
      target: this.contentEl,
      props: {
        app: this.app,
        courseId: defaultCourse.id,
        courseTitle: defaultCourse.title
      }
    });
  }
  async onClose() {
    if (this.component) {
      unmount(this.component);
      this.component = null;
    }
  }
};

// src/main.ts
var VIEW_TYPE_STUDY_HUB = "study-hub-view";
var StudyHubView = class extends import_obsidian5.ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    __publicField(this, "component");
    __publicField(this, "plugin");
    this.plugin = plugin;
  }
  getViewType() {
    return VIEW_TYPE_STUDY_HUB;
  }
  getDisplayText() {
    return "Study Hub";
  }
  async onOpen() {
    this.contentEl.empty();
    this.contentEl.addClass("study-hub-view-leaf");
    this.contentEl.style.overflowY = "auto";
    this.contentEl.style.height = "100%";
    this.contentEl.style.padding = "0";
    this.component = mount(App2, {
      target: this.contentEl,
      props: {
        app: this.app,
        plugin: this.plugin
      }
    });
  }
  async onClose() {
    if (this.component) {
      unmount(this.component);
    }
  }
};
var StudyHubPlugin = class extends import_obsidian5.Plugin {
  async onload() {
    const savedData = await this.loadData();
    initStudyHubStore(this, savedData);
    this.registerView(
      VIEW_TYPE_STUDY_HUB,
      (leaf) => new StudyHubView(leaf, this)
    );
    this.registerView(
      VIEW_TYPE_CONCEPT_MAP,
      (leaf) => new ConceptMapView(leaf)
    );
    this.addRibbonIcon("graduation-cap", "Open Study Hub", () => {
      this.activateView();
    });
    this.addRibbonIcon("network", "Open 3D Concept Map", () => {
      this.activateConceptMapView();
    });
    this.addCommand({
      id: "open-study-hub",
      name: "Open Study Hub",
      callback: () => {
        this.activateView();
      }
    });
    this.addCommand({
      id: "open-3d-concept-map",
      name: "Open 3D Concept Map",
      callback: () => {
        this.activateConceptMapView();
      }
    });
  }
  async activateView() {
    const { workspace } = this.app;
    let leaf = null;
    const leaves = workspace.getLeavesOfType(VIEW_TYPE_STUDY_HUB);
    if (leaves.length > 0) {
      leaf = leaves[0];
    } else {
      leaf = workspace.getLeaf("tab");
      await leaf.setViewState({ type: VIEW_TYPE_STUDY_HUB, active: true });
    }
    workspace.revealLeaf(leaf);
  }
  async activateConceptMapView() {
    const { workspace } = this.app;
    let leaf = null;
    const leaves = workspace.getLeavesOfType(VIEW_TYPE_CONCEPT_MAP);
    if (leaves.length > 0) {
      leaf = leaves[0];
    } else {
      leaf = workspace.getLeaf("tab");
      await leaf.setViewState({ type: VIEW_TYPE_CONCEPT_MAP, active: true });
    }
    workspace.revealLeaf(leaf);
  }
};
